#!/usr/bin/env bash
# Self-contained offline installer for the Quectel Pi M2 video-player demo.
# Sources are embedded below; no network / git / apt / pip needed on the board.
#
# Usage:
#   bash board-install.sh                       # install to ~/video-player-demo
#   bash board-install.sh /opt/video-player     # custom destination
#   bash board-install.sh <dest> [install.sh options...]
#
# install.sh writes the launcher to ~/.local/bin/video-player-demo and a desktop
# entry to ~/.local/share/applications/. It also installs a dedicated app icon
# (SVG + 48/64/128/256 PNG into ~/.local/share/icons/hicolor/), a ~/Desktop
# shortcut and a GNOME Dash favourite, plus the bundled Desktop Icons NG (DING)
# extension (user-level, no root/apt/network) so a freshly flashed board shows
# icons on the desktop. GNOME Shell loads extensions at startup, so on a running
# Wayland session the desktop icons appear after one log out / log in.
# System deps (GTK4, GStreamer, MPP, librknnrt, librga, numpy) ship with the
# Debian 13 board image.
set -euo pipefail
DEST="${1:-$HOME/video-player-demo}"
if [ $# -gt 0 ]; then shift; fi
mkdir -p "$DEST"
printf '[board-install] unpacking %d source files -> %s\n' 74 "$DEST"
base64 -d <<'__BOARD_PAYLOAD__' | tar -xzf - -C "$DEST"
