CQCIEwA=
__BOARD_PAYLOAD__
chmod +x "$DEST/install.sh"
printf '[board-install] running install.sh --require-board\n'
cd "$DEST"
OUT="$(bash ./install.sh --require-board "$@" 2>&1)" || { printf '%s\n' "$OUT"; exit 1; }
printf '%s\n' "$OUT"
LAUNCH="$(printf '%s\n' "$OUT" | sed -n 's/.*launcher installed: //p')"
LAUNCH="${LAUNCH:-$HOME/.local/bin/video-player-demo}"
printf '\n[board-install] done.\n'
printf '  sources:  %s\n' "$DEST"
printf '  launcher: %s\n' "$LAUNCH"
printf '  run:      %s --demo <video>\n' "$LAUNCH"
